import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Kumar has a regular {n}-gon, with one coin on each vertex. Fix an integer {step} with 1 ≤ {step} ≤ floor((n−1)/2). In one operation, he selects a vertex v, takes one coin from each of the two vertices that are exactly {step} edges away from v along the polygon (one in the clockwise and one in the counterclockwise direction), adds one coin to v, and keeps one coin for himself. He can perform such an operation only when both of those two distance-{step} vertices have at least one coin. He stops when he can no longer perform any operation. Let N_max be the maximum number of coins Kumar can collect, and N_min be the minimum number. Compute 1000·N_max + N_min.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Generate n and step so that the induced distance-step graph has cycles of length at least 3
# and step is not n/2 (to avoid coinciding neighbors).
import math
for _ in range(10000):
    n = rng.randint(12, 3000)
    step = rng.randint(1, (n - 1) // 2)
    d = math.gcd(n, step)
    L = n // d
    if L >= 3:
        return {'n': n, 'step': step}
# Fallback deterministic safe values
return {'n': 120, 'step': 7}

    def verifier(assign):
# Validate and compute the answer using the derived closed-form.
import math
n = assign.get('n')
step = assign.get('step')
# Basic validation
if not isinstance(n, int) or not isinstance(step, int):
    # invalid types
    return (False, None)  # invalid
if n < 3:
    # need at least a triangle
    return (False, None)
if step < 1 or step > (n - 1) // 2:
    # avoid degenerate step, and step = n/2 is excluded by this bound
    return (False, None)
d = math.gcd(n, step)
L = n // d
if L < 3:
    # the induced distance-step graph must have cycle-length at least 3 per component
    return (False, None)
# Derived formulas:
# The distance-step graph on the cycle decomposes into d disjoint cycles, each of length L = n/d.
# On each component, with initial 1 coin per vertex and the local operation (take from two neighbors at graph distance 1 in that component,
# add 1 to the center, collect 1), the maximum number of operations is L - 2 and the minimum is ceil(L / 3).
# Globally, operations across components are independent; counts add.
N_max = n - 2 * d
N_min = d * ((L + 2) // 3)  # ceil(L/3)
answer = 1000 * N_max + N_min
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

